export const PI=3.141592653589793,TAU=6.283185307179586,HALF_PI=1.5707963267948966;export function psin(t){t-=Math.floor(t/TAU+.5)*TAU,t>HALF_PI?t=PI-t:t<-HALF_PI&&(t=-PI-t);const n=t*t;return t*(1+n*(-1/6+n*(1/120+n*(-1/5040+n*(1/362880+n*(-1/39916800+n*(1/6227020800)))))))}export const pcos=t=>psin(t+HALF_PI);export function pangle(t,n){const r=Math.sqrt(t*t+n*n)||1;if(t/=r,n/=r,t<-.99999999)return n<0?-PI:PI;for(let e=0;e<6;e++){const i=Math.sqrt((1+t)/2);n=n/(2*i),t=i}const o=n*n;return 64*n*(1+o*(1/6+o*(3/40+o*(15/336))))}export function rngFrom(t){let n=t>>>0||1;return()=>{n=n+1831565813>>>0;let r=n;return r=Math.imul(r^r>>>15,r|1),r^=r+Math.imul(r^r>>>7,r|61),((r^r>>>14)>>>0)/4294967296}}
